package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/golang/protobuf/proto"
)

func extractStructDefinition(srcPath string) (*proto.Message, error) {
	// Read the entire file into memory
	fileData, err := ioutil.ReadFile(srcPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read %s: %w", srcPath, err)
	}

	// Parse the JSON data (assuming it's structured as a proto message)
	var msg *proto.Message
	err = json.Unmarshal(fileData, &msg)
	if err != nil {
		return nil, fmt.Errorf("unmarshaling failed: %w", err)
	}
	return msg, nil
}

func generateAvroSchema(msg *proto.Message) ([]byte, error) {
	// Generate the Avro schema for the given protobuf message
	schema, err := proto.Marshaler().MarshalJSON(msg)
	if err != nil {
		return nil, fmt.Errorf("marshaling to JSON failed: %w", err)
	}

	// Convert the JSON to Avro format
	return convertToAvro(schema)
}

func convertToAvro(data []byte) ([]byte, error) {
	// Use the avro-go library to convert the JSON data to Avro
	reader := bytes.NewReader(data)
	writer, err := avro.NewWriter(os.Stdout)
	if err != nil {
		return nil, fmt.Errorf("creating writer: %w", err)
	}
	defer writer.Close()

	if err := writer.Write([]byte(`{"type":"record","name":"avro_struct","fields":[{"name":"field1","type":"string"},{"name":"field2","type":["null","int"]}]}`)); err != nil {
		return nil, fmt.Errorf("writing record schema failed: %w", err)
	}
	if _, err := reader.Seek(0, 0); err != nil {
		return nil, fmt.Errorf("seeking back to beginning of input stream: %w", err)
	}

	if _, err := writer.Write(reader); err != nil {
		return nil, fmt.Errorf("writing data to Avro schema failed: %w", err)
	}
	if err := writer.Flush(); err != nil {
		return nil, fmt.Errorf("flushing writer failed: %w", err)
	}

	return writer.Bytes(), nil
}

func main() {
	srcPath := "path/to/your/go/source/file.go"
	structName := "YourStructName" // Replace with the actual struct name

	msg, err := extractStructDefinition(srcPath)
	if err != nil {
		fmt.Printf("Error extracting struct definition: %v\n", err)
		os.Exit(1)
	}

	schema, err := generateAvroSchema(msg)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		os.Exit(1)
	}

	_, err = os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating output file: %v\n", err)
		os.Exit(1)
	}

	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), schema, 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema to file: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Avro schema generated successfully!")
}
```

